import os
import re

import boto3
from opensearchpy import OpenSearch, RequestsHttpConnection
from requests_aws4auth import AWS4Auth

from bedrock_client import invoke_claude
from config import OPENSEARCH_INDEX, REGION, get_opensearch_host

try:
    from onnx_embed import get_embedding
except ImportError:
    from sentence_transformers import SentenceTransformer

    _model = None

    def get_embedding(text: str) -> list[float]:
        global _model
        if _model is None:
            _model = SentenceTransformer("all-MiniLM-L6-v2")
        return _model.encode(text).tolist()


def get_opensearch_client() -> OpenSearch:
    credentials = boto3.Session().get_credentials()
    if not credentials:
        raise RuntimeError("AWS credentials are unavailable.")

    auth = AWS4Auth(
        credentials.access_key,
        credentials.secret_key,
        REGION,
        "es",
        session_token=credentials.token,
    )

    return OpenSearch(
        hosts=[{"host": get_opensearch_host(), "port": 443}],
        http_auth=auth,
        use_ssl=True,
        verify_certs=True,
        connection_class=RequestsHttpConnection,
    )


def retrieve(question: str, top_k: int = 5) -> list[dict]:
    client = get_opensearch_client()
    response = client.search(
        index=OPENSEARCH_INDEX,
        body={
            "size": top_k,
            "query": {
                "knn": {
                    "embedding": {
                        "vector": get_embedding(question),
                        "k": top_k,
                    }
                }
            },
        },
    )

    return [
        {
            "content": hit["_source"]["content"],
            "source": hit["_source"]["source"],
            "score": hit.get("_score"),
        }
        for hit in response["hits"]["hits"]
    ]


def generate_cited_answer(
    question: str,
    chunks: list[dict],
    trace_id: str | None = None,
) -> tuple[str, dict]:
    context = "\n\n".join(
        f"[Source {index}: {chunk['source']}]\n{chunk['content']}"
        for index, chunk in enumerate(chunks, start=1)
    )

    result = invoke_claude(
        "Answer using only the supplied context. "
        "If the answer is absent, say exactly: "
        "'I cannot find this information in the provided documents.' "
        "When answering, cite sources using [Source N].\n\n"
        f"CONTEXT:\n{context}\n\nQUESTION: {question}",
        max_tokens=500,
        stage="retrieval_answer",
        question=question,
        trace_id=trace_id,
    )

    return result["text"], {
        "input": result["input_tokens"],
        "output": result["output_tokens"],
    }


    return result["text"], {
        "input": result["input_tokens"],
        "output": result["output_tokens"],
    }


def check_grounding(answer: str, chunks: list[dict]) -> bool:
    citations = re.findall(r"\[?Source\s+(\d+)\]?", answer, re.IGNORECASE)
    if not citations:
        return "cannot find this information" in answer.lower()
    return all(1 <= int(number) <= len(chunks) for number in citations)


def run_retrieval_agent(
    question: str,
    trace_id: str | None = None,
) -> dict:
    chunks = retrieve(question)

    if not chunks:
        return {
            "success": False,
            "answer": "No relevant documents were found.",
            "sources": [],
            "metadata": {
                "chunk_count": 0,
                "grounded": False,
                "token_usage": {"input": 0, "output": 0},
                "token_breakdown": {},
            },
        }

    answer, usage = generate_cited_answer(
        question,
        chunks,
        trace_id,
    )

    grounded = check_grounding(answer, chunks)
    no_answer = "cannot find this information" in answer.lower()

    return {
        "success": grounded and not no_answer,
        "answer": answer,
        "sources": [chunk["source"] for chunk in chunks],
        "metadata": {
            "chunk_count": len(chunks),
            "grounded": grounded,
            "token_usage": usage,
            "token_breakdown": {
                "retrieval_answer": usage,
            },
        },
    }

retrieval_agent = run_retrieval_agent
